/*
 * Surroundflix page hook. Generated by the Python builder; edit the
 * template in src/surroundflix/templates/page.js, not the build output.
 *
 * Cadmium (Netflix's player) serialises its manifest request with
 * JSON.stringify before encrypting and sending it. That request carries a
 * "profiles" list of the formats the browser claims to support. We wrap
 * JSON.stringify and append extra audio profiles to that list. Netflix's
 * own code is never modified, so a new Cadmium version doesn't break this
 * unless Netflix changes the request format itself.
 *
 * DRM is untouched: audio still comes through Netflix's normal, licensed
 * playback path.
 */
(function () {
  "use strict";

  var CONFIG = /*__SURROUNDFLIX_CONFIG__*/ null;
  if (!CONFIG || window.__surroundflix) return;

  // Prefixes Netflix uses for audio profile names. A "profiles" array is
  // only touched if it already contains one of these, so unrelated data
  // that happens to use the same key is left alone.
  var AUDIO_PROFILE = /^(heaac|xheaac|ddplus)-/;
  var MANIFEST_KEYS = ["params", "profiles", "profileGroups"];
  var MAX_DEPTH = 5;
  // The extension writes the preset chosen in its popup here.
  var PRESET_ATTR = "data-surroundflix-preset";

  var state = {
    version: CONFIG.version,
    preset: CONFIG.preset,
    dolbySupported: null,
    requested: [],
    patchedRequests: 0,
    lastPatchedAt: null,
    lastManifestAudio: null
  };

  // Mirrors the state into an attribute on <html> so the content script,
  // and through it the popup, can read it from its isolated world.
  var STATUS_ATTR = "data-surroundflix-status";
  function publishStatus() {
    var root = document.documentElement;
    if (!root || !root.setAttribute) return;
    root.setAttribute(STATUS_ATTR, nativeStringify({
      preset: state.preset,
      requested: state.requested,
      received: state.lastManifestAudio,
      patchedRequests: state.patchedRequests
    }));
  }

  function log() {
    if (!CONFIG.debug) return;
    var args = Array.prototype.slice.call(arguments);
    args.unshift("[Surroundflix]");
    console.log.apply(console, args);
  }

  function dolbySupported() {
    if (!CONFIG.checkDolby) return true;
    if (state.dolbySupported === null) {
      try {
        state.dolbySupported = !!(window.MediaSource &&
          window.MediaSource.isTypeSupported('audio/mp4; codecs="ec-3"'));
      } catch (err) {
        state.dolbySupported = false;
      }
    }
    return state.dolbySupported;
  }

  function currentPreset() {
    var root = document.documentElement;
    var chosen = root && root.getAttribute(PRESET_ATTR);
    // The attribute can be set by any script on the page: accept only our
    // own preset names (not "constructor", "__proto__"...).
    return chosen && Object.prototype.hasOwnProperty.call(CONFIG.presets, chosen) ? chosen : CONFIG.preset;
  }

  // Read at request time, so a change in the popup applies to the next title.
  function wantedProfiles() {
    if (!dolbySupported()) return CONFIG.noDolbyProfiles;
    state.preset = currentPreset();
    return CONFIG.presets[state.preset];
  }

  function isAudioProfileList(arr) {
    if (!Array.isArray(arr)) return false;
    for (var i = 0; i < arr.length; i++) {
      if (typeof arr[i] === "string" && AUDIO_PROFILE.test(arr[i])) return true;
    }
    return false;
  }

  function addProfiles(arr, wanted) {
    var added = 0;
    for (var i = 0; i < wanted.length; i++) {
      if (arr.indexOf(wanted[i]) === -1) {
        arr.push(wanted[i]);
        added++;
      }
    }
    return added;
  }

  // Handles both the flat params.profiles shape and the newer
  // params.profileGroups[].profiles one.
  function walk(node, wanted, depth) {
    if (!node || typeof node !== "object" || depth > MAX_DEPTH) return 0;
    var added = 0;
    if (Array.isArray(node)) {
      for (var i = 0; i < node.length; i++) added += walk(node[i], wanted, depth + 1);
      return added;
    }
    var keys = Object.keys(node);
    for (var k = 0; k < keys.length; k++) {
      var value = node[keys[k]];
      if (keys[k] === "profiles" && isAudioProfileList(value)) {
        added += addProfiles(value, wanted);
      } else if (value && typeof value === "object") {
        added += walk(value, wanted, depth + 1);
      }
    }
    return added;
  }

  function looksLikeManifestRequest(value) {
    if (!value || typeof value !== "object" || Array.isArray(value)) return false;
    for (var i = 0; i < MANIFEST_KEYS.length; i++) {
      if (Object.prototype.hasOwnProperty.call(value, MANIFEST_KEYS[i])) return true;
    }
    return false;
  }

  // Records which audio profiles Netflix actually sent back, so users can
  // paste window.__surroundflix into a bug report. The manifest's shape has
  // changed over the years (audio_tracks / audioTracks, streams /
  // downloadables, nested under result or payload), so search for it.
  var AUDIO_TRACK_KEYS = ["audio_tracks", "audioTracks"];
  var STREAM_KEYS = ["streams", "downloadables"];
  var PROFILE_KEYS = ["content_profile", "contentProfile", "profile"];

  function findAudioTracks(node, depth) {
    if (!node || typeof node !== "object" || depth > 6) return null;
    var i;
    if (Array.isArray(node)) {
      for (i = 0; i < node.length && i < 50; i++) {
        var found = findAudioTracks(node[i], depth + 1);
        if (found) return found;
      }
      return null;
    }
    for (i = 0; i < AUDIO_TRACK_KEYS.length; i++) {
      var tracks = node[AUDIO_TRACK_KEYS[i]];
      if (Array.isArray(tracks) && tracks.length) return tracks;
    }
    var keys = Object.keys(node);
    for (i = 0; i < keys.length; i++) {
      var value = node[keys[i]];
      if (value && typeof value === "object") {
        var deeper = findAudioTracks(value, depth + 1);
        if (deeper) return deeper;
      }
    }
    return null;
  }

  function firstKey(obj, names) {
    for (var i = 0; i < names.length; i++) {
      if (obj && obj[names[i]] != null) return obj[names[i]];
    }
    return null;
  }

  function audioProfilesOf(tracks) {
    var seen = [];
    function add(cp) {
      if (typeof cp === "string" && AUDIO_PROFILE.test(cp) && seen.indexOf(cp) === -1) seen.push(cp);
    }
    for (var i = 0; i < tracks.length; i++) {
      add(firstKey(tracks[i], PROFILE_KEYS));
      var streams = firstKey(tracks[i], STREAM_KEYS);
      if (!Array.isArray(streams)) continue;
      for (var j = 0; j < streams.length; j++) add(firstKey(streams[j], PROFILE_KEYS));
    }
    return seen;
  }

  function inspectManifestResponse(value) {
    var tracks = findAudioTracks(value, 0);
    if (!tracks) return false;
    var seen = audioProfilesOf(tracks);
    if (!seen.length) {
      log("audio tracks found but no profile names; first track keys:", Object.keys(tracks[0] || {}));
      return false;
    }
    state.lastManifestAudio = seen;
    publishStatus();
    log("audio profiles returned by Netflix:", seen);
    return true;
  }

  function mentionsAudioTracks(text) {
    return text.indexOf("audio_tracks") !== -1 || text.indexOf("audioTracks") !== -1;
  }

  var nativeStringify = JSON.stringify;
  var nativeParse = JSON.parse;

  function stringify(value, replacer, space) {
    try {
      if (looksLikeManifestRequest(value)) {
        var wanted = wantedProfiles();
        var added = walk(value, wanted, 0);
        if (added > 0) {
          state.requested = wanted.slice();
          state.patchedRequests++;
          state.lastPatchedAt = new Date().toISOString();
          publishStatus();
          log("manifest request patched, added", added, "profile(s)", wanted);
        }
      }
    } catch (err) {
      log("patch skipped:", err);
    }
    return nativeStringify.call(this, value, replacer, space);
  }

  function parse(text, reviver) {
    var result = nativeParse.call(this, text, reviver);
    try {
      if (result && typeof result === "object" && typeof text === "string" && mentionsAudioTracks(text)) {
        if (!inspectManifestResponse(result)) {
          log("response mentions audio tracks but none were read; top-level keys:", Object.keys(result));
        }
      }
    } catch (err) {
      log("inspect skipped:", err);
    }
    return result;
  }

  // Some responses are decoded with fetch's Response.json(), which doesn't
  // go through JSON.parse.
  var nativeResponseJson = window.Response && window.Response.prototype.json;
  if (nativeResponseJson) {
    window.Response.prototype.json = function () {
      return nativeResponseJson.call(this).then(function (data) {
        try {
          if (data && typeof data === "object") inspectManifestResponse(data);
        } catch (err) {
          log("inspect skipped:", err);
        }
        return data;
      });
    };
    window.Response.prototype.json.toString = function () { return nativeResponseJson.toString(); };
  }

  // Keep the wrappers looking like the originals to other page code.
  stringify.toString = function () { return nativeStringify.toString(); };
  parse.toString = function () { return nativeParse.toString(); };

  JSON.stringify = stringify;
  JSON.parse = parse;

  Object.defineProperty(window, "__surroundflix", { value: state, configurable: false });
  publishStatus();
  log("active, default preset", CONFIG.preset);
})();
